-- Importance: 98. Session ownership, token transfers, preferences, and private reminders protect account data.
begin;
\ir fixtures/setup.sql.inc
select plan(38);
select has_table('public','devices','public.devices exists');
select has_table('public','notification_preferences','public.notification_preferences exists');
select has_table('public','reminders','public.reminders exists');
select ok(not has_table_privilege('authenticated','public.devices','INSERT'),'No direct device writes');
select ok(not has_column_privilege('authenticated','public.devices','expo_token','SELECT'),'Tokens have no client read grant');
select ok(not has_table_privilege('authenticated','public.reminders','UPDATE'),'No direct reminder updates');
select ok(not has_function_privilege('anon','public.register_device(jsonb)','EXECUTE'),'Anon cannot register');
select ok(not has_function_privilege('authenticated','public.claim_due_jobs(integer,integer)','EXECUTE'),'Clients cannot claim jobs');
select pg_temp.as_user(1);
set local role authenticated;
select is(public.get_notification_preferences()->'data'->>'version','0','Missing preferences use version zero');
select is(public.get_notification_preferences()->'data'->>'messageAlerts','false','Alerts start off');
select is(public.save_notification_preferences('{"messageAlerts":true,"defaultEventReminderMinutes":15,"quietStart":"22:00","quietEnd":"07:00","timezone":"Europe/Warsaw"}',0)->'data'->>'version','1','Explicit preference save');
select is(public.save_notification_preferences('{"messageAlerts":false,"timezone":"UTC"}',0)->'error'->>'code','CONFLICT','Stale preferences conflict');
select is(public.save_notification_preferences('{"messageAlerts":true,"quietStart":"07:00","quietEnd":"07:00","timezone":"UTC"}',1)->'error'->>'code','VALIDATION','Equal quiet times rejected');
select is(public.save_notification_preferences('{"messageAlerts":true,"quietStart":"25:00","quietEnd":"07:00","timezone":"UTC"}',1)->'error'->>'code','VALIDATION','Invalid wall time rejected');
select is(public.save_notification_preferences('{"messageAlerts":true,"timezone":"Invalid/Zone"}',1)->'error'->>'code','VALIDATION','Invalid zone rejected');
select is(public.register_device('{"installationId":"90000000-0000-4000-8000-000000000001","token":"ExpoPushToken[fixture-one]","platform":"android","permission":"denied"}')->'error'->>'code','VALIDATION','Denied permission cannot carry a token');
create temporary table device_saved as select public.register_device('{"installationId":"90000000-0000-4000-8000-000000000001","token":"ExpoPushToken[fixture-one]","platform":"android","permission":"allowed"}') result;
select ok((select (result->>'ok')::boolean from device_saved),'Allowed device saved');
select is(public.register_device('{"installationId":"90000000-0000-4000-8000-000000000001","token":"ExpoPushToken[fixture-one]","platform":"android","permission":"allowed"}'),(select result from device_saved),'Same registration is stable');
select pg_temp.as_user(2);
select is((select count(*)::integer from public.devices),0,'Partner cannot read another device');
select is((select count(*)::integer from public.notification_preferences),0,'Partner cannot read preferences');
select ok((public.register_device('{"installationId":"90000000-0000-4000-8000-000000000002","token":"ExpoPushToken[fixture-one]","platform":"ios","permission":"allowed"}')->>'ok')::boolean,'A token can move to the current authenticated installation');
reset role;
select is((select count(*)::integer from public.devices where expo_token='ExpoPushToken[fixture-one]' and revoked_at is null),1,'Only one active token owner');
select ok((select revoked_at is not null and expo_token is null from public.devices where installation_id='90000000-0000-4000-8000-000000000001'),'Previous token owner revoked');
select is((select session_id from public.devices where installation_id='90000000-0000-4000-8000-000000000002'),'20000000-0000-4000-8000-000000000002'::uuid,'Device bound to actual Auth session');
insert into public.events(id,pair_id,created_by,owner,visibility,title,timezone,starts_at,ends_at) values
 ('91000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','a','private','Private','UTC',now()+interval '2 days',now()+interval '2 days 1 hour');
set local role authenticated;
select is(public.set_reminder('{"id":"92000000-0000-4000-8000-000000000001","pairId":"30000000-0000-4000-8000-000000000001","eventId":"91000000-0000-4000-8000-000000000001","minutesBefore":15,"active":true}', '93000000-0000-4000-8000-000000000001')->'error'->>'code','FORBIDDEN','Partner cannot remind a private event');
select pg_temp.as_user(1);
create temporary table reminder_input as select '{"id":"92000000-0000-4000-8000-000000000001","pairId":"30000000-0000-4000-8000-000000000001","eventId":"91000000-0000-4000-8000-000000000001","minutesBefore":15,"active":true}'::jsonb value;
create temporary table reminder_saved as select public.set_reminder((select value from reminder_input),'93000000-0000-4000-8000-000000000001') result;
select is((select result->'data'->>'state' from reminder_saved),'scheduled','Owner can schedule');
select is(public.set_reminder((select value from reminder_input),'93000000-0000-4000-8000-000000000001'),(select result from reminder_saved),'Retry keeps receipt');
select is(public.set_reminder((select value||'{"minutesBefore":60}' from reminder_input),'93000000-0000-4000-8000-000000000001')->'error'->>'code','CONFLICT','Command ID binds payload');
select is(public.get_reminder('91000000-0000-4000-8000-000000000001',null)->'data'->>'version','1','Owner reminder read');
select is(public.set_reminder((select value||'{"expectedVersion":7}' from reminder_input),'93000000-0000-4000-8000-000000000002')->'error'->>'code','CONFLICT','Stale reminder edit denied');
select is(public.set_reminder((select value||'{"expectedVersion":1,"active":false,"minutesBefore":null}' from reminder_input),'93000000-0000-4000-8000-000000000003')->'data'->>'state','off','Explicit reminder disable accepts a null schedule');
select pg_temp.as_user(3);
select is((select count(*)::integer from public.reminders),0,'Other pair cannot read reminder');
select is(public.get_reminder('91000000-0000-4000-8000-000000000001',null)->'data','null'::jsonb,'Guessed source gives no reminder');
select pg_temp.as_user(2);
select ok((public.revoke_device('90000000-0000-4000-8000-000000000002')->>'ok')::boolean,'Local signout revokes device');
reset role;
select is((select count(*)::integer from public.devices where user_id in ('10000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000002') and revoked_at is null),0,'Revocation removes active delivery token');
select pg_temp.as_user(1);
delete from auth.sessions where user_id='10000000-0000-4000-8000-000000000001';
set local role authenticated;
select is((select count(*)::integer from public.notification_preferences),0,'Revoked session has no preference reads');
select is((select count(*)::integer from public.reminders),0,'Revoked session has no reminder reads');
reset role;
select ok(not has_function_privilege('authenticated','private.invoke_notification_worker(text,jsonb)','EXECUTE'),'Clients cannot invoke cron HTTP');
select * from finish();
rollback;
